head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldods17011";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldods17011.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_usrStatNorm_onclick
 * @description 「승인」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_usrStatNorm_onclick = function(e){
    try {
        scwin.usrStatNorm()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods17011.btn_usrStatNorm_onclick' }); }
};

/**
 * @method
 * @name btn_usrStatRetn_onclick
 * @description 「반려」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_usrStatRetn_onclick = function(e){
    try {
        scwin.usrStatRetn()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods17011.btn_usrStatRetn_onclick' }); }
};

/**
 * @method
 * @name btn_list_onclick
 * @description 「목록으로」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_list_onclick = function(e){
    try {
        scwin.list()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods17011.btn_list_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_usrStatNorm
 * @description usr Stat Norm 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_usrStatNorm = async function () {
    const sbmOptions = {
        id: "tx_fn_usrStatNorm",
        method: "post",
        action: "/usradm/user.do",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_usrStatRetn
 * @description usr Stat Retn 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_usrStatRetn = async function () {
    const sbmOptions = {
        id: "tx_fn_usrStatRetn",
        method: "post",
        action: "/usradm/user.do",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/usradm/user.do",
        ref: "dma_loadListReq",
        target: "dlt_usradmFormUsrStatIdArr=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name list
 * @description list 처리
 * @returns {void}
 * @hidden N
 */
scwin.list = function () {
    $('#ipt_SCREN_ID', $('#searchForm')).val("/jldods17001/jldods17001.xml");
    $('#ipt_SCREN_PROCES_TP_CD', $('#searchForm')).val("01");
    $('#ipt_method', $('#searchForm')).val("readUserList");
    $('#searchForm').submit();
};

/**
 * @method
 * @name usrStatNorm
 * @description usr Stat Norm 처리
 * @returns {void}
 * @hidden N
 */
scwin.usrStatNorm = function () {
    confirmF('회원가입을 승인처리 하시겠습니까?', function() {
            $('#ipt_usrStatId', $('#searchForm')).val("APPL");
            $('#ipt_SCREN_ID', $('#searchForm')).val("/jldods17011/jldods17011.xml");
            $('#ipt_SCREN_PROCES_TP_CD', $('#searchForm')).val("03");
            $('#ipt_method', $('#searchForm')).val("updateUsrStatId");
            $.ajax({ type: "POST", url: "/usradm/user.do", data: $("#searchForm").serialize(), dataType: 'JSON', success: async function(data) {
                        if (data.result === 1) {
                            await alertE("회원가입이 승인처리 되었습니다.", async function() {
                                    $('#ipt_SCREN_ID', $('#searchForm')).val("/jldods17001/jldods17001.xml");
                                    $('#ipt_SCREN_PROCES_TP_CD', $('#searchForm')).val("01");
                                    $('#ipt_method', $('#searchForm')).val("readUserList");
                                    await scwin.tx_fn_usrStatNorm();
                            });
                        } else {
                            await alertE("상장법인의 총 사용자는 " + data.result + "명을 초과할 수 없습니다.");
                        }
                    }, error: async function(request, status, error) {
                        await alertE("회원가입 승인처리가 실패하였습니다.\n시스템 담당자에게 문의하시기 바랍니다.");
                        return;
                    } });
    });
};

/**
 * @method
 * @name usrStatRetn
 * @description usr Stat Retn 처리
 * @returns {void}
 * @hidden N
 */
scwin.usrStatRetn = function () {
    confirmF('회원가입을 반려처리 하시겠습니까?', function() {
            $('#ipt_usrStatId', $('#searchForm')).val("RETN");
            $('#ipt_SCREN_ID', $('#searchForm')).val("/jldods17011/jldods17011.xml");
            $('#ipt_SCREN_PROCES_TP_CD', $('#searchForm')).val("03");
            $('#ipt_method', $('#searchForm')).val("updateUsrStatId");
            $.ajax({ type: "POST", url: "/usradm/user.do", data: $("#searchForm").serialize(), dataType: 'JSON', success: async function(data) {
                        if (data.result === 1) {
                            await alertE("회원가입이 반려처리 되었습니다.", async function() {
                                    $('#ipt_SCREN_ID', $('#searchForm')).val("/jldods17001/jldods17001.xml");
                                    $('#ipt_SCREN_PROCES_TP_CD', $('#searchForm')).val("01");
                                    $('#ipt_method', $('#searchForm')).val("readUserList");
                                    await scwin.tx_fn_usrStatRetn();
                            });
                        } else {
                            await alertE("회원가입 반려처리가 실패하였습니다.\n시스템 담당자에게 문의하시기 바랍니다.");
                        }
                    }, error: async function(request, status, error) {
                        await alertE("회원가입 반려 처리중 오류가 발생하였습니다.\n시스템 담당자에게 문의하시기 바랍니다.");
                        return;
                    } });
    });
};

/**
 * @method
 * @name alertE
 * @description alert E 처리
 * @param {String} msg 항목명
 * @param {*} callback callback
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.alertE = async function (msg, callback) {
    // as-is 는 화면 안 #pAlertText/#divAlertMsg 를 만졌다 — 엔진 프레임 접두 때문에
    // 그 선택자는 어디서도 못 찾는다. 표준 알림으로 낸다(메시지가 사라지지 않게).
    await $c.win.alert(msg);
    if (typeof callback === 'function') { await callback(); }
};

async function alertE(msg, callback) { return await scwin.alertE(msg, callback); }
